def ordinal_word(n):
    words = {1: 'first', 2: 'second', 3: 'third', 4: 'fourth', 5: 'fifth',
             6: 'sixth', 7: 'seventh', 8: 'eighth', 9: 'ninth', 10: 'tenth',
             11: 'eleventh', 12: 'twelfth'}
    if n in words:
        return words[n]
    return f'{n}th'

def format_list_with_and(items):
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' and ' + items[1]
    return ', '.join(items[:-1]) + ', and ' + items[-1]

def render_template(template, values):
    import re
    return re.sub(r'\{(\w+)\}', lambda m: str(values[m.group(1)]), template)

def render_template_default(template, values, default):
    import re
    return re.sub(r'\{(\w+)\}',
                   lambda m: str(values[m.group(1)]) if m.group(1) in values else default,
                   template)

def mail_merge(template, records):
    import re
    def render(rec):
        return re.sub(r'\{(\w+)\}', lambda m: str(rec[m.group(1)]), template)
    return [render(r) for r in records]

def fill_blanks(template, words):
    parts = template.split('___')
    result = parts[0]
    for i, word in enumerate(words):
        result += word + parts[i + 1]
    return result

def build_csv_line(fields):
    result = []
    for f in fields:
        if ',' in f or '"' in f:
            f = '"' + f.replace('"', '""') + '"'
        result.append(f)
    return ','.join(result)

def capitalize_sentence(s):
    if not s:
        return s
    return s[0].upper() + s[1:]

def capitalize_sentences(text):
    sentences = text.split('. ')
    capitalized = [s[0].upper() + s[1:] if s else s for s in sentences]
    return '. '.join(capitalized)

def mask_email(email):
    local, domain = email.split('@', 1)
    if len(local) <= 1:
        masked = local
    elif len(local) == 2:
        masked = local[0] + '*'
    else:
        masked = local[0] + '*' * (len(local) - 2) + local[-1]
    return masked + '@' + domain

def count_words_format(text):
    n = len(text.split())
    return f'{n} word' if n == 1 else f'{n} words'

def compress_repeated_chars(s):
    if not s:
        return ''
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

def expand_repeated_chars(s):
    import re
    result = []
    for ch, count in re.findall(r'([A-Za-z])(\d+)', s):
        result.append(ch * int(count))
    return ''.join(result)

def format_time_12h(hour, minute):
    period = 'AM' if hour < 12 else 'PM'
    h = hour % 12
    if h == 0:
        h = 12
    return f'{h}:{minute:02d} {period}'

def format_time_24h(hour, minute, ampm):
    if ampm == 'AM':
        h = 0 if hour == 12 else hour
    else:
        h = 12 if hour == 12 else hour + 12
    return f'{h:02d}:{minute:02d}'
